package local.zfttests;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import org.json.*;
public class History extends Instrumentation {
 void require(boolean b,String m){if(!b)throw new AssertionError(m);}Object get(Object o,String n)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(o);}void set(Object o,String n,Object v)throws Exception{Field f=o.getClass().getDeclaredField(n);f.setAccessible(true);f.set(o,v);}void call(Object o,String n)throws Exception{Method m=o.getClass().getDeclaredMethod(n);m.setAccessible(true);m.invoke(o);}
 public void onCreate(Bundle b){super.onCreate(b);start();}public void onStart(){Bundle out=new Bundle();try{
 Activity main=startActivitySync(new Intent().setClassName(getTargetContext(),"local.zft.NativeChat").putExtra("forum_id","42").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));runOnMainSync(()->{try{set(main,"fixture",true);call(main,"fixture");((EditText)get(main,"input")).setText("保留原草稿");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
 ActivityMonitor monitor=addMonitor("local.zft.NativeChat",null,false);runOnMainSync(()->{View v=main.getWindow().getDecorView().findViewWithTag("local.zft.avatar");require(v!=null&&v.isClickable(),"avatar opens history");v.performClick();});Activity history=waitForMonitorWithTimeout(monitor,5000);require(history!=null&&history!=main,"separate history page");waitForIdleSync();
 runOnMainSync(()->{try{require("8".equals(get(history,"historyUser")),"clicked author id retained");require("42".equals(get(history,"forum")),"same forum");set(history,"fixture",true);call(history,"fixture");require(((TextView)get(history,"heading")).getText().toString().equals("圈主的发言"),"clear author heading");Object model=get(history,"model");java.util.TreeMap<Long,JSONObject> messages=(java.util.TreeMap<Long,JSONObject>)model.getClass().getField("messages").get(model);messages.get(2L).put("OriginData",new JSONArray().put(messages.get(1L)));call(history,"refresh");require(((List<?>)get(history,"rows")).size()==2,"server-provided replies retain conversation context");require(!history.getWindow().getDecorView().findViewWithTag("local.zft.tab.0").isShown(),"history has back instead of main tabs");Method params=history.getClass().getDeclaredMethod("chatParams",int.class,boolean.class,long.class,JSONObject.class);params.setAccessible(true);Map<?,?> p=(Map<?,?>)params.invoke(history,0,false,88L,new JSONObject());require("8".equals(p.get("chat_user_id"))&&"88".equals(p.get("before_id")),"original author and pagination parameters");require(!p.containsKey("user_id")&&!p.containsKey("view_type"),"does not replace signed-in identity");}catch(Exception e){throw new RuntimeException(e);}});waitForIdleSync();
 Thread.sleep(800);android.graphics.Bitmap b=getUiAutomation().takeScreenshot();try(java.io.FileOutputStream f=new java.io.FileOutputStream(new java.io.File(getTargetContext().getExternalFilesDir(null),"history-preview.png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,f);}b.recycle();
 runOnMainSync(()->history.getWindow().getDecorView().findViewWithTag("local.zft.message-text").performClick());waitForIdleSync();Thread.sleep(500);runOnMainSync(()->{try{require(((Long)get(main,"replyId"))==1L,"history reply returns selected message");require("保留原草稿".equals(((EditText)get(main,"input")).getText().toString()),"history does not overwrite chat draft");require(((TextView)get(main,"replySummary")).getText().toString().contains("欢迎"),"reply preview restored");}catch(Exception e){throw new RuntimeException(e);}});removeMonitor(monitor);out.putString("result","PASS avatar author/room routing, filtered history, original query parameters, pagination cursor, reply return and draft preservation");finish(-1,out);
 }catch(Throwable e){out.putString("result","FAIL: "+e);finish(0,out);}}
}
